CREATE TABLE partner_roles(id UUID PRIMARY KEY,partner_id UUID NOT NULL REFERENCES partners(id),code VARCHAR(80) NOT NULL,name VARCHAR(160) NOT NULL,system_role BOOLEAN NOT NULL DEFAULT FALSE,permissions TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,UNIQUE(partner_id,code));
CREATE TABLE partner_memberships(id UUID PRIMARY KEY,partner_id UUID NOT NULL REFERENCES partners(id),user_id VARCHAR(255) NOT NULL,role_id UUID NOT NULL REFERENCES partner_roles(id),status VARCHAR(30) NOT NULL,invited_by VARCHAR(255) NOT NULL,invited_at TIMESTAMPTZ NOT NULL,accepted_at TIMESTAMPTZ,revoked_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,UNIQUE(partner_id,user_id));
CREATE INDEX idx_partner_membership_context ON partner_memberships(partner_id,user_id,status);
CREATE TABLE partner_invitations(id UUID PRIMARY KEY,partner_id UUID NOT NULL REFERENCES partners(id),contact VARCHAR(320) NOT NULL,role_id UUID NOT NULL REFERENCES partner_roles(id),token_hash VARCHAR(128) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,status VARCHAR(30) NOT NULL,invited_by VARCHAR(255) NOT NULL,created_at TIMESTAMPTZ NOT NULL,accepted_at TIMESTAMPTZ);
CREATE TABLE partner_staff_audit(id UUID PRIMARY KEY,partner_id UUID NOT NULL,actor_user_id VARCHAR(255) NOT NULL,target_user_id VARCHAR(255),action VARCHAR(100) NOT NULL,details TEXT,occurred_at TIMESTAMPTZ NOT NULL);
CREATE TABLE partner_billing_preferences(partner_id UUID PRIMARY KEY REFERENCES partners(id),invoice_email VARCHAR(320),billing_address TEXT,tax_identifier VARCHAR(100),purchase_order_required BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ NOT NULL);
